  window.toggle_showComplement = function (on) { showComp = !!on; update(); };
  window.toggle_showReferenceCurves = function (on) { showRef = !!on; update(); };

  /* ---------- hover / click ---------- */
  function curvesA() {
    var arr = [];
    if (showRef) refsA.forEach(function (r) {
      arr.push({ v: r.v, th: 45, name: 'Textbook curve: v\u2080 = ' + r.v + ' m/s at 45\u00B0' });
    });
    arr.push({ v: v0a, th: 45, name: 'Live curve (panel a): v\u2080 = ' + v0a + ' m/s at 45\u00B0' });
    return arr;
  }
  function curvesB() {
    var arr = [];
    if (showRef) refsB.forEach(function (r) {
      arr.push({ v: 50, th: r.th, name: 'Textbook curve: ' + r.th + '\u00B0 at 50 m/s' });
    });
    arr.push({ v: 50, th: thB, name: 'Live curve (panel b): ' + thB + '\u00B0 at 50 m/s' });
    if (showComp && Math.abs(thB - 45) > 0.5)
      arr.push({ v: 50, th: 90 - thB, name: 'Complementary curve: ' + (90 - thB) + '\u00B0 at 50 m/s' });
    return arr;
  }
  function tipText(c) {
    return c.name + ' \u2014 R = ' + fmt(Rg(c.v, c.th)) + ' m, apex = ' + fmt(Hg(c.v, c.th)) +
      ' m, flight time = ' + Tg(c.v, c.th).toFixed(1) + ' s';
  }
  function popupFor(c) {
    var R = Rg(c.v, c.th);
    showPopup(
      'v\u2080 = ' + c.v + ' m/s at \u03B8 = ' + c.th + '\u00B0',
      'Range R = v\u2080\u00B2 sin(2\u03B8)/g = (' + c.v + ')\u00B2 \u00D7 sin(' + (2 * c.th) +
      '\u00B0) / 9.8 = ' + fmt(R) + ' m. The apex height v\u2080\u00B2sin\u00B2\u03B8/(2g) = ' +
      fmt(Hg(c.v, c.th)) + ' m and the flight time 2v\u2080sin\u03B8/g = ' + Tg(c.v, c.th).toFixed(1) +
      ' s. Because speed enters squared, scaling v\u2080 by a factor k scales R by k\u00B2; because the angle enters only through sin(2\u03B8), ' +
      c.th + '\u00B0 and ' + (90 - c.th) + '\u00B0 give exactly the same range with very different heights.'
    );
  }
  function bindHover(canvas, chart, getCurves) {
    canvas.addEventListener('mousemove', function (e) {
      var r = canvas.getBoundingClientRect();
      var mx = e.clientX - r.left, my = e.clientY - r.top;
      var xs = chart.scales.x, ys = chart.scales.y;
      var xv = xs.getValueForPixel(mx);
      var best = null, bd = 1e9;
      getCurves().forEach(function (c) {
        var R = Rg(c.v, c.th);
        if (xv < 0 || xv > R) return;
        var d = Math.abs(ys.getPixelForValue(yAt(c.v, c.th, xv)) - my);
        if (d < bd) { bd = d; best = c; }
      });
      var tol = Math.max(7, chart.height * 0.045);
      if (best && bd < tol) {
        canvas.style.cursor = 'pointer';
        canvas.$hit = best;
        showTooltip(tipText(best), e);
      } else {
        canvas.style.cursor = 'default';
        canvas.$hit = null;
        hideTooltip();
      }
    });
    canvas.addEventListener('mouseleave', function () { canvas.$hit = null; hideTooltip(); });
    canvas.addEventListener('click', function () { if (canvas.$hit) popupFor(canvas.$hit); });
  }
  bindHover(cvA, chartA, curvesA);
  bindHover(cvB, chartB, curvesB);

  /* ---------- demo steps ---------- */
  var steps = [
    {
      title: 'The original figure',
      narration: 'Both panels show the textbook curves: three speeds at 45\u00B0 on top, three angles at 50 m/s below. Every arc starts and ends on the same ground line, and each range bar measures one arc.',
      state: { launchSpeed: 30, launchAngle: 45, showComplement: true, showReferenceCurves: 'on' }
    },
    {
      title: 'Range grows with v\u2080\u00B2',
      narration: 'Drag the speed slider in panel (a) from 30 to 40 to 50 m/s with the angle pinned at 45\u00B0. The range bar stretches from 91.8 m to 163 m to 255 m \u2014 each step is a bigger jump than the last, because range scales as the square of speed.',
      state: { launchSpeed: 50, launchAngle: 45, showComplement: true, showReferenceCurves: 'on' }
    },
    {
      title: 'Doubling speed quadruples range',
      narration: 'Set v\u2080 to 60 m/s: the range is four times what it was at 30 m/s. The apex rises by the same factor of four, and the whole parabola is simply a scaled copy.',
      state: { launchSpeed: 60, launchAngle: 45, showComplement: true, showReferenceCurves: 'on' }
    },
    {
      title: 'A shallow launch',
      narration: 'Now hold the speed at 50 m/s and drag the angle in panel (b) down to 15\u00B0. The arc is flat and fast, landing at 128 m \u2014 the projectile has plenty of horizontal speed but almost no time in the air.',
      state: { launchSpeed: 50, launchAngle: 15, showComplement: true, showReferenceCurves: 'on' }
    },
    {
      title: 'Complementary angles share a landing point',
      narration: 'With the complement shown, the 75\u00B0 partner curve appears \u2014 tall, slow, and steep \u2014 yet it touches down on exactly the same dashed vertical at 128 m. Equal range, wildly different flight.',
      state: { launchSpeed: 50, launchAngle: 75, showComplement: true, showReferenceCurves: 'on' }
    },
    {
      title: '45\u00B0 is the peak',
      narration: 'Sweep the angle back to 45\u00B0 and the two complementary curves merge into one. This is where sin(2\u03B8) equals 1 and the range is maximum: 255 m.',
      state: { launchSpeed: 50, launchAngle: 45, showComplement: true, showReferenceCurves: 'off' }
    }
  ];
  var si = 0;
  function applyStep(i) {
    si = (i + steps.length) % steps.length;
    var s = steps[si].state;
    v0a = s.launchSpeed;
    thB = s.launchAngle;
    showComp = !!s.showComplement;
    showRef = (s.showReferenceCurves === 'on' || s.showReferenceCurves === true);
    document.getElementById('launchSpeedInput').value = v0a;
    document.getElementById('launchSpeedVal').value = v0a;
    document.getElementById('launchAngleInput').value = thB;
    document.getElementById('launchAngleVal').value = thB;
    document.getElementById('showComplementInput').checked = showComp;
    document.getElementById('showReferenceCurvesInput').checked = showRef;
    document.getElementById('demoNarration').textContent = steps[si].narration;
    document.getElementById('stepTitle').textContent = 'Step ' + (si + 1) + ' \u2014 ' + steps[si].title;
    document.getElementById('stepLabel').textContent = (si + 1) + ' / ' + steps.length;
    update();
  }
  window.prevStep = function () { applyStep(si - 1); };
  window.nextStep = function () { applyStep(si + 1); };
  window.showInsight = function () {
    showPopup('Key idea: R = v\u2080\u00B2 sin(2\u03B8) / g',
      'One formula packs both panels. Speed enters squared, so panel (a) grows quadratically: 30 \u2192 60 m/s multiplies the range by four. The angle enters only through sin(2\u03B8), which is largest at \u03B8 = 45\u00B0 and takes the same value at \u03B8 and 90\u00B0 \u2212 \u03B8, so complementary launches in panel (b) land together even though the steep one climbs far higher and stays airborne much longer.');
  };

  /* ---------- go ---------- */
  document.addEventListener('fig-resize', function () {
    chartA.resize(); chartB.resize();
  });
  applyStep(0);
  window.__markRendered();
})();
